/// <summary>
/// Provides a collection of static lookup methods to use in forms.
/// </summary>
class AVADAILookupHelper
{
}

Method.Source:
    /// <summary>
    /// Lookup report names.
    /// </summary>
    /// <param name = "_lookupCtrl">Control for which to perform the lookup</param>
    public static void reportName(FormStringControl _lookupCtrl, AVADAIReportType  _reportType)
    {
        AVADAILookUpTmp         reportLookup;
        Query                   lookupQuery;
        QueryBuildDataSource    qbds;
        ERSOLUTIONTABLE         erSolutionTable;

        switch (_reportType)
        {
            case AVADAIReportType::SSRS:
            var     reports = Microsoft.Dynamics.Ax.Xpp.MetadataSupport::ReportNames();
            while (reports.MoveNext())
            {
                reportLookup.clear();
                reportLookup.LookupItemName = reports.Current;
                reportLookup.insert();
            }
                break;
         case AVADAIReportType::BusinessDocuments:
            while select erSolutionTable
            {
                reportLookup.clear();
                reportLookup.LookupItemName = erSolutionTable.Name;
                reportLookup.insert();
            }
                break;
            default:
                return;
                break;
        }

        // Create a custom Query
        lookupQuery     = new Query();
        qbds            = lookupQuery.addDataSource(tablenum(AVADAILookUpTmp));
        qbds.addOrderByField(fieldNum(AVADAILookUpTmp,LookupItemname));

		SysTableLookup sysTableLookup = SysTableLookup::newParameters(tablenum(AVADAILookUpTmp), _lookupCtrl);

        // Display the Name field in the lookup form.
        sysTableLookup.addLookupfield(fieldnum(AVADAILookUpTmp, LookupItemName));
        sysTableLookup.parmQuery(lookupQuery);
        sysTableLookup.parmTmpBuffer(reportLookup);
        sysTableLookup.performFormLookup();
    }

    /// <summary>
    /// Lookup report designs.
    /// </summary>
    /// <param name = "_lookupCtrl">Control for which to perform the lookup</param>
    /// <param name = "_reportName">Name of the report of which the designs must be shown</param>
    public static void reportDesignName(FormStringControl _lookupCtrl, ReportName _reportName)
    {
        if (_reportName)
        {
            AVADAILookUpTmp         reportDesignLookup;

            Microsoft.Dynamics.AX.Metadata.MetaModel.AxReport report = Microsoft.Dynamics.Ax.Xpp.MetadataSupport::GetReport(_reportName);
            if (report != null)
            {
                var designs = report.get_Designs();
                if (designs != null)
                {
                    for (int i = 0; i < designs.get_Count(); ++i)
                    {
                        Microsoft.Dynamics.AX.Metadata.MetaModel.AxReportDesign design = designs.GetObject(i);
                        if (design != null)
                        {
                            reportDesignLookup.clear();
                            reportDesignLookup.LookupItemName = design.Name;
                            reportDesignLookup.insert();
                        }
                    }

                    Query                   lookupQuery;
                    QueryBuildDataSource    qbds;



                    // Create a custom Query
                    lookupQuery = new Query();
                    qbds = lookupQuery.addDataSource(tablenum(AVADAILookUpTmp));
                    qbds.addOrderByField(fieldNum(AVADAILookUpTmp,LookupItemname));
                    SysTableLookup sysTableLookup = SysTableLookup::newParameters(tablenum(AVADAILookUpTmp), _lookupCtrl);

                    // Display the Name field in the lookup form.
                    sysTableLookup.addLookupfield(fieldnum(AVADAILookUpTmp, LookupItemName));
                    sysTableLookup.parmQuery(lookupQuery);
					sysTableLookup.parmTmpBuffer(reportDesignLookup);
                    sysTableLookup.performFormLookup();
                }
            }
        }
    }

/// <summary>
/// Lookup form names.
/// </summary>
/// <param name = "_lookupCtrl">Control for which to perform the lookup</param>
public static void formName(FormStringControl _lookupCtrl)
{
    AVADAILookUpTmp         formLookup;

    var forms = Microsoft.Dynamics.Ax.Xpp.MetadataSupport::FormNames();
    while (forms.MoveNext())
    {
        formLookup.clear();
        formLookup.LookupItemName = forms.Current;
        formLookup.insert();
    }

    Query                   lookupQuery;
    QueryBuildDataSource    qbds;

    // Create a custom Query
    lookupQuery = new Query();
    qbds        = lookupQuery.addDataSource(tablenum(AVADAILookUpTmp));
    qbds.addOrderByField(fieldNum(AVADAILookUpTmp,LookupItemname));
    SysTableLookup sysTableLookup = SysTableLookup::newParameters(tablenum(AVADAILookUpTmp), _lookupCtrl);

    // Display the Name field in the lookup form.
    sysTableLookup.addLookupfield(fieldnum(AVADAILookUpTmp, LookupItemName));
    sysTableLookup.parmQuery(lookupQuery);
    sysTableLookup.parmTmpBuffer(formLookup);
    sysTableLookup.performFormLookup();
}

/// <summary>
/// Lookup form datasource names.
/// </summary>
/// <param name = "_lookupCtrl">Control for which to perform the lookup</param>
/// <param name = "_formName">Form of which the datasources shall be shown</param>
public static void formDatasourceName(FormStringControl _lookupCtrl, FormName _formName)
{
    if (_formName)
    {
        Args                    args;
        FormRun                 fr;
        AVADAILookUpTmp         formDatasourceLookup;
        Query                   lookupQuery;
        QueryBuildDataSource    qbds;
        SysTableLookup          sysTableLookup = SysTableLookup::newParameters(tablenum(AVADAILookUpTmp), _lookupCtrl);

        args = new Args();
        args.name(_formName);
        fr = ClassFactory.formRunClass(args);

        for (int ii = 1; ii <= fr.form().dataSourceCount(); ++ii)
        {
            formDatasourceLookup.clear();
            formDatasourceLookup.LookupItemName = fr.form().dataSource(ii).name();
            formDatasourceLookup.insert();
        }

        // Display the Name field in the lookup form.
        sysTableLookup.addLookupfield(fieldnum(AVADAILookUpTmp, LookupItemName));

        // Create a custom Query
        lookupQuery     = new Query();
        qbds            = lookupQuery.addDataSource(tablenum(AVADAILookUpTmp));
        qbds.addOrderByField(fieldNum(AVADAILookUpTmp,LookupItemname));
        sysTableLookup.parmQuery(lookupQuery);
        sysTableLookup.parmTmpBuffer(formDatasourceLookup);
        sysTableLookup.performFormLookup();
    }
}

/// <summary>
/// Show field names of form datasource.
/// </summary>
/// <param name = "_lookupCtrl">Control for which to perform the lookup</param>
/// <param name = "_formName">Form in which the datasource is</param>
/// <param name = "_datasourceName">Name of the datasource which fields shall be shown</param>
public static void formDatasourceFieldName(FormStringControl _lookupCtrl, FormName _formName, DatasourceName _datasourceName)
{
    if (_formName && _datasourceName)
    {
        Args                    args;
        FormRun                 fr;
        AVADAILookUpTmp         formDatasourceFieldLookup;
        Query                   lookupQuery;
        QueryBuildDataSource    qbds;
        SysTableLookup          sysTableLookup = SysTableLookup::newParameters(tablenum(AVADAILookUpTmp), _lookupCtrl);

        args = new Args();
        args.name(_formName);
        fr = ClassFactory.formRunClass(args);

        for (int i = 1; i <= fr.form().dataSourceCount(); ++i)
        {
            if (fr.form().dataSource(i).name() == _datasourceName)
            {
                TableId tableId = fr.form().dataSource(i).table();
                if (tableId)
                {
                    DictTable dictTable = new DictTable(tableId);
                    if (dictTable)
                    {
                        for (int j = 1; j <= dictTable.fieldCnt(); ++j)
                        {
                            formDatasourceFieldLookup.clear();
                            formDatasourceFieldLookup.LookupItemName = fieldId2Name(tableId, dictTable.fieldCnt2Id(j));
                            formDatasourceFieldLookup.insert();
                        }
                    }
                }
            }
        }

        // Display the Name field in the lookup form.
        sysTableLookup.addLookupfield(fieldnum(AVADAILookUpTmp, LookupItemName));

        // Create a custom Query
        lookupQuery     = new Query();
        qbds            = lookupQuery.addDataSource(tablenum(AVADAILookUpTmp));
        qbds.addOrderByField(fieldNum(AVADAILookUpTmp,LookupItemname));
        sysTableLookup.parmQuery(lookupQuery);
        sysTableLookup.parmTmpBuffer(formDatasourceFieldLookup);
        sysTableLookup.performFormLookup();
    }
}

/// <summary>
/// Lookup table names.
/// </summary>
/// <param name = "_lookupCtrl">Control for which to perform the lookup</param>
public static void tableName(FormStringControl _lookupCtrl)
{
    AVADAILookUpTmp         reportLookup;
    Query                   lookupQuery;
    QueryBuildDataSource    qbds;

    var tables = Microsoft.Dynamics.Ax.Xpp.MetadataSupport::TableNames();
    while (tables.MoveNext())
    {
        reportLookup.clear();
        reportLookup.LookupItemName = tables.Current;
        reportLookup.insert();
    }

    SysTableLookup sysTableLookup = SysTableLookup::newParameters(tablenum(AVADAILookUpTmp), _lookupCtrl);

    // Display the Name field in the lookup form.
    sysTableLookup.addLookupfield(fieldnum(AVADAILookUpTmp, LookupItemName));

    // Create a custom Query
    lookupQuery     = new Query();
    qbds            = lookupQuery.addDataSource(tablenum(AVADAILookUpTmp));
    qbds.addOrderByField(fieldNum(AVADAILookUpTmp,LookupItemname));
    sysTableLookup.parmQuery(lookupQuery);
    sysTableLookup.parmTmpBuffer(reportLookup);
    sysTableLookup.performFormLookup();
}

/// <summary>
/// Lookup field names.
/// </summary>
/// <param name = "_lookupCtrl">Control for which to perform the lookup</param>
/// <param name = "_tableName">Name of the table of which the fields shall be shown</param>
public static void fieldName(FormStringControl _lookupCtrl, TableName _tableName)
{
    DictMethod          dictMethod;

    if (_tableName)
    {
        TableId tableId = tableName2Id(_tableName);
        if (tableId)
        {
            DictTable dictTable = new DictTable(tableId);

            AVADAILookUpTmp fieldNameLookup;

            while (dictTable)
            {
                for (int j = 1; j <= dictTable.fieldCnt(); ++j)
                {
                    fieldNameLookup.clear();
                    fieldNameLookup.LookupItemName = fieldId2Name(tableId, dictTable.fieldCnt2Id(j));
                    fieldNameLookup.insert();
                }

                for (int xx = 1; xx <= dictTable.objectMethodCnt(); ++xx)
                {
                    dictMethod = DictTable.objectMethodObject(xx);
                    if(dictMethod.displayType())
                    {
                        fieldNameLookup.clear();
                        fieldNameLookup.LookupItemName = DictMethod.name() + '()';
                        fieldNameLookup.insert();
                    }
                }

                if (dictTable.extends())
                {
                    dictTable = new DictTable(dictTable.extends());
                }
                else
                {
                    dictTable = null;
                }
            }

            // Create a custom Query
            Query                   lookupQuery;
            QueryBuildDataSource    qbds;
            lookupQuery = new Query();
            qbds        = lookupQuery.addDataSource(tablenum(AVADAILookUpTmp));
            qbds.addOrderByField(fieldNum(AVADAILookUpTmp,LookupItemname));

            //lookup form
            SysTableLookup sysTableLookup = SysTableLookup::newParameters(tablenum(AVADAILookUpTmp), _lookupCtrl);

            // Display the Name field in the lookup form.
            sysTableLookup.addLookupfield(fieldnum(AVADAILookUpTmp, LookupItemName));
            sysTableLookup.parmQuery(lookupQuery);
            sysTableLookup.parmTmpBuffer(fieldNameLookup);
            sysTableLookup.performFormLookup();
        }
    }
}
